#!/usr/bin/env python3
"""Compiler and checker for business-analysis spaces.

An analysis space is one topic folder under workspace/docs/business-analysis/:
a tree of typed, cross-linked markdown documents (the authored source of
truth) plus machine-generated views under _generated/. This script is the
single mechanical authority over that structure. It contains zero document
taxonomy of its own: every doc type, section token, id kind, row schema and
row schema comes from the shipped schema data file
(skill-content/business-analysis/data/space-schema.json). The compiler
enforces structural and semantic correctness, never authoring-volume caps.

Subcommands:
  init          create a new space skeleton
  stub          create one born-compliant typed document
  check         structural validation; --gate approval adds the gate rules
  render        (re)generate the _generated/ views deterministically
  resolve       map ids to owning docs, statuses and statement hashes
  verify-import validate a backlog import's criterion ids against the space

Stdlib only. Exit 0 on success, 1 on findings/violations, 2 on usage.
Finding format mirrors tools/validate.py: SEVERITY path:line [check]
message | Fix: remediation, sorted by (path, line, check).
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import sys
import tempfile
import unicodedata
from dataclasses import dataclass, field
from datetime import date, datetime, timezone
from pathlib import Path

DEFAULT_SCHEMA = (Path(__file__).resolve().parent.parent
                  / "skill-content" / "business-analysis" / "data"
                  / "space-schema.json")

GENERATED_DIR = "_generated"
GENERATED_MARKER = "<!-- generated by ba_compile render; do not edit by hand -->"
GENERATED_VIEWS = ("index.md", "registry.md", "registry.json", "backlinks.md",
                   "status.md", "open-questions.md")
PACKAGE_CONTRACT_VERSION = 3

EM_DASH = "—"
ABSOLUTE_PATH_RE = re.compile(r"(?:^|[\s\"'`(=])(?:/Users/|/home/|[A-Za-z]:\\\\|~/)")
LINK_RE = re.compile(r"\[([^\]]+)\]\(([^)\s]+)(?:\s+\"[^\"]*\")?\)")
# Vault wikilink grammar, shared with vault_check (single parsing home).
WIKILINK_RE = re.compile(r"(?P<embed>!?)\[\[(?P<inner>[^\[\]\n]+?)\]\]")
GENERATED_BODY_BLOCKS = (
    ("## Related knowledge <!-- sec: relations:generated:start -->",
     "<!-- sec: relations:generated:end -->"),
    ("## Contents <!-- sec: structural:generated:start -->",
     "<!-- sec: structural:generated:end -->"),
)
INLINE_CODE_RE = re.compile(r"`[^`]*`")


def split_wikilink(inner: str) -> tuple[str, str, str]:
    """Split a wikilink body into (target, anchor, alias). The alias
    separator is '|' or its table-escaped form '\\|'."""
    alias = ""
    for sep in ("\\|", "|"):
        if sep in inner:
            inner, alias = inner.split(sep, 1)
            break
    target, _, anchor = inner.partition("#")
    return target.strip(), anchor.strip(), alias.strip()


def split_row_cells(raw: str) -> list[str]:
    """Split a table row on unescaped pipes only: an escaped alias pipe
    ('\\|') inside a cell wikilink stays inside its cell."""
    return re.split(r"(?<!\\)\|", raw.strip().strip("|"))


def normalize_cell(cell: str) -> str:
    """Collapse id-aliased wikilinks to their bare ids. The normalized
    form feeds the rows dict (registry, render, cited_by, statements and
    their sha256 hashes), so rewriting a bare citation cell into a
    wikilink never changes a statement hash."""
    def collapse(match: re.Match) -> str:
        _target, _anchor, alias = split_wikilink(match.group("inner"))
        if NAMESPACED_ID_RE.fullmatch(alias) or BARE_ID_RE.fullmatch(alias):
            return alias
        return match.group(0)
    return WIKILINK_RE.sub(collapse, cell).strip()
SEC_RE = re.compile(r"<!--\s*sec:\s*([a-z_]+)\s*-->")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
NAMESPACED_ID_RE = re.compile(r"\b(BR|AC|AS|OQ|DEC)-([A-Z]{2,4})-(\d{3,})\b")
BARE_ID_RE = re.compile(r"\b(BR|AC|AS|OQ|DEC)-(\d{3,})\b")


# ---------------------------------------------------------------------------
# Naming: plain per-folder names; typed content is <slug>-<suffix>.md.
# Display identity lives in titles (the vault's title layer), never in
# filenames, so basenames may repeat across folders.
# ---------------------------------------------------------------------------


def named_file_name(schema: dict, doc_type: str) -> str:
    return schema["doc_types"][doc_type]["location"]["name"]


def space_overview_rel(schema: dict) -> str:
    return named_file_name(schema, "space")


def node_overview_rel(schema: dict, node_rel: str) -> str:
    if node_rel == "":
        return space_overview_rel(schema)
    return f"{node_rel}/{named_file_name(schema, 'domain')}"


def root_file_rels(schema: dict) -> list[str]:
    """The required root skeleton files, plain contract names."""
    return [named_file_name(schema, t)
            for t in ("space", "glossary", "actor_roster", "budget_set")]


# Every check id this compiler can emit. The test suite's builder registry
# stays in lockstep with this tuple: a check without a firing fixture
# cannot merge (same doctrine as tools/validate.py).
CHECK_IDS = (
    "space_layout", "frontmatter_schema", "status_legality",
    "required_sections", "content_bans", "dead_links",
    "id_format", "id_unique", "id_minting", "id_links", "row_schema",
    "semantic_links", "approval_preconditions",
    "br_uncited", "gate_approval",
    "generated_freshness", "future_dates", "identifier_shape",
    "diagram_identifiers",
)

STATUS_RANK = {"draft": 0, "in_review": 1, "approved": 2}


@dataclass(frozen=True)
class Finding:
    severity: str  # "error" | "warning"
    path: str
    line: int
    check: str
    message: str
    remediation: str


@dataclass
class Table:
    section: str | None
    header_line: int
    columns: list[str]
    rows: list[tuple[int, list[str]]]       # NORMALIZED cells
    # Cells exactly as authored. Enforcement (mint shape, bare citation
    # cells) reads the raw evidence; registry, render, cited_by and the
    # statement hashes read the normalized rows, so a cell rewrite from
    # bare id to wikilink never trips a statement-hash tripwire.
    raw_cells: list[tuple[int, list[str]]] = field(default_factory=list)


@dataclass
class Doc:
    rel: str
    abs_path: Path
    fm: dict
    fm_end: int
    doc_type: str
    node: str
    lines: list[str] = field(default_factory=list)
    fenced: set = field(default_factory=set)
    fences: list = field(default_factory=list)  # (start, end, info)
    headings: list = field(default_factory=list)  # (lineno, level, text)
    sections: dict = field(default_factory=dict)  # token -> (h_line, start, end)
    tables: list = field(default_factory=list)
    summary_lines: int = 0
    links: list = field(default_factory=list)  # (lineno, text, target)
    wikilinks: list = field(default_factory=list)  # (lineno, embed, target, anchor, alias)


@dataclass
class Space:
    root: Path
    schema: dict
    slug: str = ""  # the space directory name; the naming chain's root
    docs: dict = field(default_factory=dict)     # rel -> Doc
    nodes: dict = field(default_factory=dict)    # rel -> code ("" = root)
    ids: dict = field(default_factory=dict)      # id -> {kind, doc, row, line}
    broken: bool = False  # ambiguity class present; render must refuse
    vault_root: Path | None = None  # the docs tree root; wikilinks resolve here


# ---------------------------------------------------------------------------
# Parsing
# ---------------------------------------------------------------------------


def parse_frontmatter(text: str) -> tuple[dict, int, str | None]:
    """Minimal YAML subset: scalar `key: value` and lists of `- item` lines.
    Returns (frontmatter, body start line 1-based, error or None)."""
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return {}, 1, "missing frontmatter block"
    fm: dict = {}
    current_list: str | None = None
    for i in range(1, len(lines)):
        raw = lines[i]
        stripped = raw.strip()
        if stripped == "---":
            return fm, i + 2, None
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("- ") and current_list:
            fm[current_list].append(stripped[2:].strip().strip("\"'"))
            continue
        if ":" in stripped:
            key, _, value = stripped.partition(":")
            key = key.strip()
            value = value.strip().strip("\"'")
            if value == "":
                fm[key] = []
                current_list = key
            else:
                current_list = None
                if value in ("true", "false"):
                    fm[key] = value == "true"
                elif value.isdigit():
                    fm[key] = int(value)
                else:
                    fm[key] = value
            continue
        return fm, i + 1, f"unparseable frontmatter line: {stripped[:40]}"
    return fm, 1, "unterminated frontmatter block"


def mask_generated_body_blocks(text: str) -> str:
    """Blank compiler-owned blocks while preserving authored line numbers."""
    lines = text.splitlines()
    masked = list(lines)
    for start, end in GENERATED_BODY_BLOCKS:
        active = False
        for index, line in enumerate(lines):
            if line.strip() == start:
                active = True
            if active:
                masked[index] = ""
            if active and line.strip() == end:
                active = False
    return "\n".join(masked)


def heading_has_emoji(line: str) -> bool:
    for ch in line:
        code = ord(ch)
        if code >= 0x1F000:
            return True
        if 0x2600 <= code <= 0x27BF or 0x2B00 <= code <= 0x2BFF or code == 0xFE0F:
            return True
        if unicodedata.category(ch) == "So":
            return True
    return False


def parse_doc_body(doc: Doc) -> None:
    """Fill headings, sections, summary, tables and links from doc.lines."""
    in_fence = False
    fence_start = 0
    fence_info = ""
    for idx, line in enumerate(doc.lines, start=1):
        if line.lstrip().startswith("```"):
            if not in_fence:
                fence_start = idx
                fence_info = line.lstrip()[3:].strip().lower()
            else:
                doc.fences.append((fence_start, idx, fence_info))
            in_fence = not in_fence
            doc.fenced.add(idx)
            continue
        if in_fence:
            doc.fenced.add(idx)

    h1_line = 0
    first_h2 = 0
    for idx, line in enumerate(doc.lines, start=1):
        if idx < doc.fm_end or idx in doc.fenced:
            continue
        m = re.match(r"^(#{1,6})\s+(.*)$", line)
        if m:
            level = len(m.group(1))
            doc.headings.append((idx, level, m.group(2).strip()))
            if level == 1 and not h1_line:
                h1_line = idx
            if level == 2 and not first_h2:
                first_h2 = idx

    if h1_line:
        end = first_h2 if first_h2 else len(doc.lines) + 1
        doc.summary_lines = sum(
            1 for i in range(h1_line + 1, end)
            if doc.lines[i - 1].strip() and i not in doc.fenced
        )

    h2s = [(idx, text) for idx, level, text in doc.headings if level == 2]
    for pos, (idx, text) in enumerate(h2s):
        m = SEC_RE.search(text)
        token = m.group(1) if m else None
        end = h2s[pos + 1][0] if pos + 1 < len(h2s) else len(doc.lines) + 1
        if token and token not in doc.sections:
            doc.sections[token] = (idx, idx + 1, end)

    def section_of(lineno: int) -> str | None:
        for token, (_h, start, end) in doc.sections.items():
            if start <= lineno < end:
                return token
        return None

    idx = doc.fm_end
    total = len(doc.lines)
    while idx <= total:
        line = doc.lines[idx - 1]
        if idx not in doc.fenced and line.strip().startswith("|"):
            block_start = idx
            block = []
            while idx <= total and idx not in doc.fenced \
                    and doc.lines[idx - 1].strip().startswith("|"):
                block.append((idx, doc.lines[idx - 1]))
                idx += 1
            if len(block) >= 2 and set(block[1][1].replace("|", "").strip()) <= set("-: "):
                columns = [c.strip().lower() for c in block[0][1].strip().strip("|").split("|")]
                rows = []
                raw_cells = []
                for lineno, raw in block[2:]:
                    cells = [c.strip() for c in split_row_cells(raw)]
                    raw_cells.append((lineno, cells))
                    rows.append((lineno, [normalize_cell(c) for c in cells]))
                doc.tables.append(Table(section_of(block_start), block[0][0],
                                        columns, rows, raw_cells))
            continue
        idx += 1

    for idx, line in enumerate(doc.lines, start=1):
        if idx < doc.fm_end or idx in doc.fenced:
            continue
        scrubbed = INLINE_CODE_RE.sub(" ", line)
        for m in LINK_RE.finditer(scrubbed):
            doc.links.append((idx, m.group(1), m.group(2)))
        for m in WIKILINK_RE.finditer(scrubbed):
            target, anchor, alias = split_wikilink(m.group("inner"))
            doc.wikilinks.append(
                (idx, m.group("embed") == "!", target, anchor, alias))


# ---------------------------------------------------------------------------
# Space scan
# ---------------------------------------------------------------------------


def classify_location(schema: dict, space_slug: str,
                      rel_parts: tuple[str, ...]) -> tuple[str, str] | None:
    """Return (node_rel, expected_type) for a markdown file path, or None
    when the location is illegal. Named files carry their plain contract
    names; typed folder content is <slug>-<filename_suffix>.md."""
    parts = list(rel_parts)
    node: list[str] = []
    while len(parts) > 2 and parts[0] == "domains":
        node.extend(parts[:2])
        parts = parts[2:]
    node_rel = "/".join(node)
    is_root = node_rel == ""
    if len(parts) == 1:
        name = parts[0]
        for type_name, spec in schema["doc_types"].items():
            loc = spec["location"]
            if loc["kind"] != "named_file":
                continue
            if name != named_file_name(schema, type_name):
                continue
            if loc.get("root_only") and not is_root:
                return None
            if loc.get("domain_only") and is_root:
                return None
            return node_rel, type_name
        return None
    if len(parts) == 2:
        folder, name = parts
        for type_name, spec in schema["doc_types"].items():
            loc = spec["location"]
            if loc["kind"] != "folder" or loc["folder"] != folder:
                continue
            if loc.get("root_only") and not is_root:
                return None
            suffix = loc.get("filename_suffix")
            if suffix:
                stem = name[:-3] if name.endswith(".md") else name
                if not (stem.endswith(f"-{suffix}")
                        and len(stem) > len(suffix) + 1):
                    return None
            return node_rel, type_name
        return None
    return None


def scan_space(space_dir: Path, schema: dict) -> tuple[Space, list[Finding]]:
    space = Space(root=space_dir, schema=schema, slug=space_dir.name)
    findings: list[Finding] = []

    def err(path: str, line: int, check: str, message: str, fix: str) -> None:
        findings.append(Finding("error", path, line, check, message, fix))

    def warn(path: str, line: int, check: str, message: str, fix: str) -> None:
        findings.append(Finding("warning", path, line, check, message, fix))

    if not space_dir.is_dir():
        err(space_dir.as_posix(), 1, "space_layout",
            "space directory does not exist", "run the init subcommand first")
        space.broken = True
        return space, findings

    space.nodes[""] = ""
    for dir_path in sorted(space_dir.rglob("*")):
        if not dir_path.is_dir():
            continue
        rel = dir_path.relative_to(space_dir).as_posix()
        if rel.split("/")[0] == GENERATED_DIR:
            continue
        parts = rel.split("/")
        if parts[-1] == "domains":
            continue
        is_node = len(parts) % 2 == 0 and all(
            parts[i] == "domains" for i in range(0, len(parts), 2))
        if is_node:
            space.nodes[rel] = ""

    for node_rel in sorted(space.nodes):
        overview_rel = node_overview_rel(schema, node_rel)
        if not (space_dir / overview_rel).is_file():
            overview = overview_rel.rsplit("/", 1)[-1]
            err(overview_rel, 1, "space_layout",
                f"node is missing its overview file {overview}",
                "every node carries exactly one overview document under"
                " its plain contract name")

    for name in root_file_rels(schema):
        if not (space_dir / name).is_file():
            err(name, 1, "space_layout",
                f"space root is missing required file {name}",
                "the five-file root skeleton is fixed; run init or add the file")
    if not (space_dir / GENERATED_DIR).is_dir():
        err(GENERATED_DIR, 1, "space_layout",
            "the _generated directory is missing",
            "create it (render will populate it)")

    for file_path in sorted(space_dir.rglob("*")):
        if not file_path.is_file():
            continue
        rel = file_path.relative_to(space_dir).as_posix()
        parts = rel.split("/")
        if parts[0] == GENERATED_DIR:
            if len(parts) != 2 or parts[1] not in GENERATED_VIEWS:
                warn(rel, 1, "space_layout",
                     "unexpected file inside _generated",
                     "render owns this directory; stray files are deleted")
            continue
        if file_path.suffix != ".md":
            if file_path.name == ".gitkeep":
                continue
            warn(rel, 1, "space_layout",
                 "non-markdown file in the authored tree",
                 "the space holds markdown documents only")
            continue
        text = file_path.read_text(encoding="utf-8", errors="replace")
        if text.lstrip().startswith("<!-- generated by"):
            err(rel, 1, "space_layout",
                "generated-marker file outside _generated",
                "generated views live only under _generated/")
            continue
        location = classify_location(schema, space.slug, tuple(parts))
        if location is None:
            err(rel, 1, "space_layout",
                "file location matches no document type",
                "typed content is <slug>-<filename_suffix>.md in its type"
                " folder; named files keep their plain contract names; see"
                " the space standard")
            continue
        node_rel, expected_type = location
        fm, fm_end, fm_error = parse_frontmatter(text)
        if fm_error:
            err(rel, 1, "frontmatter_schema", fm_error,
                "every authored doc opens with a --- frontmatter block")
            space.broken = True
            continue
        doc_type = fm.get("type", "")
        if doc_type not in schema["doc_types"]:
            err(rel, 1, "frontmatter_schema",
                f"unknown doc type '{doc_type}'",
                "type must be one of the schema's doc_types")
            space.broken = True
            continue
        if doc_type != expected_type:
            err(rel, 1, "frontmatter_schema",
                f"type '{doc_type}' does not match its location"
                f" (expected '{expected_type}')",
                "move the file or fix the type")
        doc = Doc(rel=rel, abs_path=file_path, fm=fm, fm_end=fm_end,
                  doc_type=doc_type, node=node_rel,
                  lines=mask_generated_body_blocks(text).splitlines())
        parse_doc_body(doc)
        space.docs[rel] = doc

    code_format = re.compile(schema["code_format"])
    seen_codes: dict[str, str] = {}
    for rel in sorted(space.docs):
        doc = space.docs[rel]
        if doc.doc_type not in ("space", "domain"):
            continue
        code = str(doc.fm.get("code", ""))
        if not code_format.match(code):
            findings.append(Finding("error", rel, 1, "frontmatter_schema",
                                    f"node code '{code}' does not match {schema['code_format']}",
                                    "declare a 2-4 uppercase-letter code"))
            continue
        if code in schema["reserved_codes"]:
            findings.append(Finding("error", rel, 1, "frontmatter_schema",
                                    f"node code '{code}' is reserved",
                                    "reserved codes cannot be claimed by nodes"))
            continue
        if code in seen_codes:
            findings.append(Finding("error", rel, 1, "frontmatter_schema",
                                    f"node code '{code}' is already used by {seen_codes[code]}",
                                    "codes are unique across the whole space"))
            continue
        aliases = doc.fm.get("aliases")
        if not (isinstance(aliases, list) and code in aliases):
            findings.append(Finding(
                "error", rel, 1, "frontmatter_schema",
                f"aliases must contain the node code '{code}'",
                "the code alias makes the bare code searchable and"
                " linkable in the vault"))
        seen_codes[code] = rel
        space.nodes[doc.node] = code

    collect_ids(space, findings)
    return space, findings


def nearest_code(space: Space, node_rel: str) -> str:
    current = node_rel
    while True:
        code = space.nodes.get(current, "")
        if code:
            return code
        if current == "":
            return ""
        current = "/".join(current.split("/")[:-2])


def collect_ids(space: Space, findings: list[Finding]) -> None:
    schema = space.schema
    for rel in sorted(space.docs):
        doc = space.docs[rel]
        spec = schema["doc_types"].get(doc.doc_type)
        if spec is None:
            continue
        code = nearest_code(space, doc.node)
        for kind in spec["mints"]:
            row_schema = schema["row_schemas"][kind.lower()]
            token = row_schema["section"]
            if token not in doc.sections:
                continue
            for table in doc.tables:
                if table.section != token:
                    continue
                if table.columns != row_schema["columns"]:
                    findings.append(Finding(
                        "error", rel, table.header_line, "row_schema",
                        f"table in section '{token}' must carry the {kind} columns"
                        f" {' | '.join(row_schema['columns'])}",
                        "row tables use the fixed English snake_case headers"))
                    continue
                raw_by_line = dict(table.raw_cells)
                citation_columns = [c for c in
                                    schema.get("id_citation_columns", [])
                                    if c in table.columns]
                for lineno, cells in table.rows:
                    if len(cells) != len(table.columns):
                        findings.append(Finding(
                            "error", rel, lineno, "row_schema",
                            f"row has {len(cells)} cells, expected {len(table.columns)}",
                            "one cell per column, in order"))
                        continue
                    row = dict(zip(table.columns, cells))
                    raw_row = dict(zip(table.columns,
                                       raw_by_line.get(lineno, cells)))
                    if WIKILINK_RE.search(raw_row.get("id", "")):
                        findings.append(Finding(
                            "error", rel, lineno, "id_minting",
                            "mint cell is written as a wikilink",
                            "a mint declares the bare id; every other"
                            " surface links to it"))
                        continue
                    for column in citation_columns:
                        residue = WIKILINK_RE.sub(" ", raw_row.get(column, ""))
                        bare = list(NAMESPACED_ID_RE.finditer(residue)) + \
                            list(BARE_ID_RE.finditer(residue))
                        for m_bare in bare:
                            findings.append(Finding(
                                "error", rel, lineno, "id_links",
                                f"bare id {m_bare.group(0)} in citation"
                                f" column '{column}'",
                                "citation cells carry escaped-pipe wikilinks"
                                " to the owning doc; vault_check.py normalize"
                                " rewrites this class"))
                    id_value = row["id"]
                    m = NAMESPACED_ID_RE.fullmatch(id_value)
                    if m:
                        row_kind, row_code = m.group(1), m.group(2)
                        if row_kind != kind:
                            findings.append(Finding(
                                "error", rel, lineno, "id_minting",
                                f"{id_value} minted in a {kind} table",
                                f"{row_kind} rows live in their own section"))
                            continue
                        if row_code != code:
                            findings.append(Finding(
                                "error", rel, lineno, "id_minting",
                                f"{id_value} carries code {row_code} but this"
                                f" node's code is {code}",
                                "an id is minted under its owning node's code;"
                                " moving a doc re-mints its ids"))
                            continue
                    else:
                        findings.append(Finding(
                            "error", rel, lineno, "id_format",
                            f"id '{id_value}' does not match {schema['id_format']}",
                            "mint KIND-CODE-NNN ids under the owning node's code"))
                        continue
                    if id_value in space.ids:
                        findings.append(Finding(
                            "error", rel, lineno, "id_unique",
                            f"{id_value} is already declared in"
                            f" {space.ids[id_value]['doc']}",
                            "an id is declared exactly once; numbers are never reused"))
                        continue
                    space.ids[id_value] = {"kind": kind, "doc": rel,
                                           "row": row, "line": lineno}


# ---------------------------------------------------------------------------
# Checks
# ---------------------------------------------------------------------------


def doc_status(doc: Doc) -> str:
    return str(doc.fm.get("status", ""))


def parse_iso_date(value: str) -> date | None:
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None


def utc_today() -> date:
    """This module's single clock read; every date this compiler writes
    or judges derives from it."""
    return datetime.now(timezone.utc).date()


def id_references(doc: Doc) -> list[tuple[int, str, str | None, bool]]:
    """All id references in a doc: (line, id, link_target or None, is_wiki).
    A wikilink whose alias is a bare id is an id citation; table id-column
    declarations are excluded (they are mints)."""
    refs: list[tuple[int, str, str | None, bool]] = []
    mint_lines = {}
    for table in doc.tables:
        for lineno, cells in table.rows:
            mint_lines.setdefault(lineno, set())
            if cells and "id" in table.columns:
                mint_lines[lineno].add(cells[table.columns.index("id")]
                                       if len(cells) > table.columns.index("id") else "")
    for idx, line in enumerate(doc.lines, start=1):
        if idx < doc.fm_end or idx in doc.fenced:
            continue
        scrubbed = INLINE_CODE_RE.sub(" ", line)
        for m in LINK_RE.finditer(scrubbed):
            text, target = m.group(1), m.group(2)
            if NAMESPACED_ID_RE.fullmatch(text) or BARE_ID_RE.fullmatch(text):
                refs.append((idx, text, target, False))
        for m in WIKILINK_RE.finditer(scrubbed):
            target, _anchor, alias = split_wikilink(m.group("inner"))
            if NAMESPACED_ID_RE.fullmatch(alias) or BARE_ID_RE.fullmatch(alias):
                refs.append((idx, alias, target, True))
        remaining = WIKILINK_RE.sub(" ", LINK_RE.sub(" ", scrubbed))
        for m in list(NAMESPACED_ID_RE.finditer(remaining)) + \
                list(BARE_ID_RE.finditer(remaining)):
            token = m.group(0)
            if token in mint_lines.get(idx, set()):
                continue
            refs.append((idx, token, None, False))
    return refs


def run_checks(space: Space, base: list[Finding], gate: bool = False,
               gate_node: str = "", today: date | None = None) -> list[Finding]:
    schema = space.schema
    findings = list(base)
    today = today or utc_today()

    def err(path, line, check, message, fix):
        findings.append(Finding("error", path, line, check, message, fix))

    def warn(path, line, check, message, fix):
        findings.append(Finding("warning", path, line, check, message, fix))

    statuses = schema["statuses"]
    fm_common = schema["frontmatter"]

    for rel in sorted(space.docs):
        doc = space.docs[rel]
        spec = schema["doc_types"][doc.doc_type]

        required = list(fm_common["required"]) + list(spec["extra_frontmatter"]["required"])
        allowed = set(required) | set(fm_common["optional"])
        for key in required:
            if key not in doc.fm:
                err(rel, 1, "frontmatter_schema",
                    f"missing frontmatter key '{key}'",
                    "the type's required keys are fixed by the schema")
        for key in doc.fm:
            if key not in allowed:
                warn(rel, 1, "frontmatter_schema",
                     f"unknown frontmatter key '{key}'",
                     "only schema-declared keys carry meaning")

        status = doc_status(doc)
        if status not in statuses:
            err(rel, 1, "status_legality",
                f"status '{status}' not in {statuses}",
                "use the schema's status enum")
        if status == "approved" and "approved_at" not in doc.fm:
            err(rel, 1, "status_legality",
                "approved doc is missing approved_at",
                "stamp approved_at: YYYY-MM-DD at the gate")
        if status != "approved" and "approved_at" in doc.fm:
            err(rel, 1, "status_legality",
                "approved_at present on a non-approved doc",
                "approved_at exists exactly when status is approved")
        if status == "superseded" and "superseded_by" not in doc.fm:
            err(rel, 1, "status_legality",
                "superseded doc is missing superseded_by",
                "name the successor documents")
        if "approved_at" in doc.fm:
            stamp = parse_iso_date(str(doc.fm["approved_at"])) \
                if DATE_RE.match(str(doc.fm["approved_at"])) else None
            if stamp is None:
                err(rel, 1, "status_legality",
                    "approved_at is not a YYYY-MM-DD calendar date",
                    "dates are ISO calendar dates; the approve verb stamps"
                    " them")
            elif stamp > today:
                err(rel, 1, "future_dates",
                    f"approved_at {doc.fm['approved_at']} is in the future",
                    "stamps come from the clock: ba_compile.py approve, or"
                    " paste UTC timestamp now --date output")

        h1s = [h for h in doc.headings if h[1] == 1]
        if len(h1s) != 1:
            err(rel, 1, "required_sections",
                f"doc has {len(h1s)} H1 headings, expected exactly 1",
                "one H1 per document, matching its title")
        for token in spec["required_sections"]:
            if token not in doc.sections:
                err(rel, 1, "required_sections",
                    f"missing section '{token}'",
                    f"add an H2 carrying <!-- sec: {token} -->")

        for idx, line in enumerate(doc.lines, start=1):
            if EM_DASH in line:
                err(rel, idx, "content_bans", "em dash character found",
                    "replace with a hyphen, comma, or rewrite")
            if idx not in doc.fenced and line.lstrip().startswith("#") \
                    and heading_has_emoji(line):
                err(rel, idx, "content_bans", "emoji in heading",
                    "headings are plain text")
            if ABSOLUTE_PATH_RE.search(line):
                err(rel, idx, "content_bans", "absolute or home path found",
                    "workspace docs use relative paths only")

        for lineno, _text, target in doc.links:
            if target.startswith(("http://", "https://", "mailto:", "#")):
                continue
            clean = target.split("#", 1)[0]
            if not clean:
                continue
            resolved = (doc.abs_path.parent / clean).resolve()
            if space.vault_root is not None:
                try:
                    resolved.relative_to(space.vault_root.resolve())
                except ValueError:
                    pass
                else:
                    err(rel, lineno, "dead_links",
                        f"vault-internal citation uses a markdown link: {target}",
                        "cite vault content as a vault-absolute wikilink"
                        " (vault_check.py normalize rewrites this class)")
                    continue
            if not resolved.exists():
                err(rel, lineno, "dead_links",
                    f"link target does not resolve: {target}",
                    "fix the path or restore the target")
        for lineno, embed, target, _anchor, _alias in doc.wikilinks:
            if not target or space.vault_root is None:
                continue
            if target.split("/")[0] == GENERATED_DIR \
                    or f"/{GENERATED_DIR}/" in target:
                err(rel, lineno, "dead_links",
                    f"authored doc links into {GENERATED_DIR}/",
                    "authored docs never depend on generated views")
                continue
            candidate = (space.vault_root
                         / (target if embed else target + ".md"))
            if not candidate.exists():
                err(rel, lineno, "dead_links",
                    f"unresolved wikilink target: {target}",
                    "targets are vault-absolute paths from the vault root")

        for lineno, id_value, target, is_wiki in id_references(doc):
            info = space.ids.get(id_value)
            if target is not None:
                if info is None:
                    err(rel, lineno, "id_links",
                        f"link cites unknown id {id_value}",
                        "cite only declared ids")
                else:
                    owner = (space.root / info["doc"]).resolve()
                    if is_wiki:
                        resolved = ((space.vault_root / (target + ".md"))
                                    .resolve()
                                    if space.vault_root is not None else None)
                    else:
                        clean = target.split("#", 1)[0]
                        resolved = (doc.abs_path.parent / clean).resolve()
                    if resolved != owner:
                        err(rel, lineno, "id_links",
                            f"{id_value} link targets {target}, but the id is"
                            f" declared in {info['doc']}",
                            "an id link targets its owning document")
            else:
                in_table = any(any(lineno == ln for ln, _ in t.rows)
                               for t in doc.tables)
                if in_table:
                    if info is None:
                        err(rel, lineno, "id_links",
                            f"cell cites unknown id {id_value}",
                            "cite only declared ids")
                elif info is None or info["doc"] != rel:
                    err(rel, lineno, "id_links",
                        f"bare id {id_value} in prose",
                        "cite ids as links to their owning doc; bare ids are"
                        " legal only in the owning doc and in table cells")

        for kind in schema["doc_types"][doc.doc_type]["mints"]:
            row_schema = schema["row_schemas"][kind.lower()]
            enum = row_schema["status_enum"]
            for id_value, info in space.ids.items():
                if info["doc"] != rel or info["kind"] != kind:
                    continue
                row = info["row"]
                if enum and row.get("status", "") not in enum:
                    err(rel, info["line"], "row_schema",
                        f"{id_value} status '{row.get('status', '')}' not in {enum}",
                        "row statuses use the schema enum")
                if "opened_on" in row:
                    stamp = parse_iso_date(row["opened_on"]) \
                        if DATE_RE.match(row["opened_on"]) else None
                    if stamp is None:
                        err(rel, info["line"], "row_schema",
                            f"{id_value} opened_on is not a YYYY-MM-DD date",
                            "stamp the date the row was opened from the"
                            " clock: paste UTC timestamp now --date output")
                    elif stamp > today:
                        err(rel, info["line"], "future_dates",
                            f"{id_value} opened_on {row['opened_on']} is in"
                            " the future",
                            "stamps come from the clock: paste UTC timestamp"
                            " now --date output")
                if kind == "AC":
                    cite_ids = re.findall(r"\b[A-Z]{2,3}-[A-Z0-9]{2,4}-\d{3,}\b",
                                          row.get("cites", ""))
                    br_cites = [c for c in cite_ids if c.startswith("BR-")]
                    if not br_cites:
                        err(rel, info["line"], "row_schema",
                            f"{id_value} cites no business rule",
                            "every criterion cites the BR ids it exercises")
                    if not row.get("verify", "").strip():
                        err(rel, info["line"], "row_schema",
                            f"{id_value} has an empty verify cell",
                            "every criterion states how it is verified")

        if status == "approved":
            for id_value, info in space.ids.items():
                if info["doc"] != rel:
                    continue
                if info["row"].get("status") == "open":
                    err(rel, info["line"], "approval_preconditions",
                        f"approved doc holds open row {id_value}",
                        "answer, confirm, strike or defer every open row"
                        " before approval")

    check_semantic_links(space, findings)
    check_identifier_language(space, findings)
    check_br_citations(space, findings, gate=gate, gate_node=gate_node)

    if gate:
        run_gate_checks(space, findings, gate_node)
    return findings


def check_identifier_language(space: Space, findings: list[Finding]) -> None:
    """Identifier positions carry ASCII machine-safe names regardless of
    the configured language axes: schema-registered table columns must
    match the naming block's identifier format, and erDiagram or
    stateDiagram identifier lines must be ASCII (text after ':' labels
    and inside double quotes is free output_language content)."""
    naming = space.schema.get("naming")
    if not naming:
        return
    id_re = re.compile(naming["identifier_format"])
    for entry in naming.get("identifier_columns", []):
        for rel in sorted(space.docs):
            doc = space.docs[rel]
            if doc.doc_type != entry["doc_type"]:
                continue
            for table in doc.tables:
                if table.section != entry["section"]:
                    continue
                column = entry["column"]
                if column not in table.columns:
                    findings.append(Finding(
                        "error", rel, table.header_line, "identifier_shape",
                        f"table in section '{entry['section']}' carries no"
                        f" '{column}' column",
                        "the identifier column is fixed; see the space"
                        " standard"))
                    continue
                col_idx = table.columns.index(column)
                for lineno, cells in table.rows:
                    value = cells[col_idx].strip("`") if col_idx < len(cells) else ""
                    if not value and entry.get("allow_empty"):
                        continue
                    if not id_re.fullmatch(value):
                        findings.append(Finding(
                            "error", rel, lineno, "identifier_shape",
                            f"field name '{value}' is not an ASCII snake_case"
                            f" identifier ({naming['identifier_format']})",
                            "technical names are written in the"
                            " terminology_language (default English) as ASCII"
                            " snake_case; glossary.md carries the"
                            " business-term to technical-name mapping"))

    for rel in sorted(space.docs):
        doc = space.docs[rel]
        for start, end, info in doc.fences:
            if not info.startswith("mermaid"):
                continue
            kind = ""
            in_note = False
            for idx in range(start + 1, end):
                line = doc.lines[idx - 1].strip()
                if not line:
                    continue
                if not kind:
                    if line.startswith("erDiagram"):
                        kind = "erDiagram"
                    elif line.startswith("stateDiagram"):
                        kind = "stateDiagram"
                    else:
                        break
                    continue
                if line.startswith("%%"):
                    continue
                if in_note:
                    if line.startswith("end note"):
                        in_note = False
                    continue
                if line.startswith("note") and ":" not in line:
                    in_note = True
                    continue
                residue = re.sub(r'"[^"]*"', "", line).split(":", 1)[0]
                if not residue.isascii():
                    token = next(
                        (w for w in residue.split() if not w.isascii()),
                        residue.strip())
                    findings.append(Finding(
                        "error", rel, idx, "diagram_identifiers",
                        f"non-ASCII identifier '{token}' in a {kind} diagram",
                        "erDiagram entities/attributes and stateDiagram"
                        " states are terminology_language names in ASCII;"
                        " localized wording belongs after ':' labels or in"
                        " prose, with the mapping in glossary.md"))


def check_semantic_links(space: Space, findings: list[Finding]) -> None:
    for rel in sorted(space.docs):
        doc = space.docs[rel]
        for key, wanted in (("governs", ("process", "entity")),
                            ("verifies", ("process", "entity", "integration"))):
            targets = doc.fm.get(key)
            if not isinstance(targets, list):
                continue
            if not targets:
                findings.append(Finding("error", rel, 1, "semantic_links",
                                        f"{key} list is empty",
                                        f"name at least one target document"))
            for target in targets:
                value = str(target)
                if not (value.startswith("[[") and value.endswith("]]")):
                    findings.append(Finding(
                        "error", rel, 1, "semantic_links",
                        f"{key} value is not a quoted vault-absolute"
                        f" wikilink: {value}",
                        "relation values are quoted wikilinks; they draw the"
                        " graph edges the vault exists to show"))
                    continue
                inner, _, _ = split_wikilink(value[2:-2])
                resolved = ((space.vault_root / (inner + ".md")).resolve()
                            if space.vault_root is not None else None)
                try:
                    target_rel = (resolved.relative_to(
                        space.root.resolve()).as_posix()
                        if resolved is not None else None)
                except ValueError:
                    target_rel = None
                target_doc = space.docs.get(target_rel) if target_rel else None
                if target_doc is None:
                    findings.append(Finding("error", rel, 1, "semantic_links",
                                            f"{key} target does not resolve: {target}",
                                            "point at an existing document"))
                elif target_doc.doc_type not in wanted:
                    findings.append(Finding("error", rel, 1, "semantic_links",
                                            f"{key} target {target} is a"
                                            f" {target_doc.doc_type}",
                                            f"{key} points at {' or '.join(wanted)} docs"))

    for node_rel in sorted(space.nodes):
        overview_rel = node_overview_rel(space.schema, node_rel)
        overview = space.docs.get(overview_rel)
        if overview is None:
            continue
        linked = set()
        for _lineno, _text, target in overview.links:
            clean = target.split("#", 1)[0]
            resolved = (overview.abs_path.parent / clean).resolve()
            try:
                linked.add(resolved.relative_to(space.root.resolve()).as_posix())
            except ValueError:
                pass
        for _lineno, _embed, target, _anchor, _alias in overview.wikilinks:
            if not target or space.vault_root is None:
                continue
            resolved = (space.vault_root / (target + ".md")).resolve()
            try:
                linked.add(resolved.relative_to(space.root.resolve()).as_posix())
            except ValueError:
                pass
        prefix = f"{node_rel}/" if node_rel else ""
        children = [r for r in space.nodes
                    if r.startswith(f"{prefix}domains/") and
                    r.count("/") == (node_rel.count("/") + 2 if node_rel else 1)]
        for child in sorted(children):
            child_overview = node_overview_rel(space.schema, child)
            if child_overview in space.docs and child_overview not in linked:
                findings.append(Finding(
                    "error", overview_rel, 1, "semantic_links",
                    f"domain_map does not link child domain {child}",
                    "the overview's domain map links every direct child"))
        own_processes = [r for r in space.docs
                         if space.docs[r].node == node_rel
                         and space.docs[r].doc_type == "process"]
        for proc in sorted(own_processes):
            if proc not in linked:
                findings.append(Finding(
                    "error", overview_rel, 1, "semantic_links",
                    f"process_map does not link {proc}",
                    "the overview's process map links every process it owns"))


def check_br_citations(space: Space, findings: list[Finding],
                       gate: bool, gate_node: str) -> None:
    cited: set[str] = set()
    for id_value, info in space.ids.items():
        if info["kind"] != "AC":
            continue
        for m in NAMESPACED_ID_RE.finditer(info["row"].get("cites", "")):
            cited.add(m.group(0))
    for id_value in sorted(space.ids):
        info = space.ids[id_value]
        if info["kind"] != "BR" or info["row"].get("status") != "active":
            continue
        if id_value in cited:
            continue
        in_scope = doc_in_node(space, info["doc"], gate_node)
        severity = "error" if gate and in_scope else "warning"
        findings.append(Finding(
            severity, info["doc"], info["line"], "br_uncited",
            f"{id_value} is cited by no acceptance criterion",
            "every active rule is exercised by at least one criterion"))


def doc_in_node(space: Space, rel: str, node_rel: str) -> bool:
    if node_rel == "":
        return True
    doc = space.docs.get(rel)
    if doc is None:
        return False
    return doc.node == node_rel or doc.node.startswith(node_rel + "/")


def run_gate_checks(space: Space, findings: list[Finding], gate_node: str) -> None:
    def err(path, line, message, fix):
        findings.append(Finding("error", path, line, "gate_approval", message, fix))

    for name in root_file_rels(space.schema):
        doc = space.docs.get(name)
        if doc is None:
            continue
        if doc_status(doc) != "approved":
            err(name, 1, f"foundation doc is {doc_status(doc)}, not approved",
                "the foundation gate precedes every domain gate")

    for rel in sorted(space.docs):
        doc = space.docs[rel]
        if not doc_in_node(space, rel, gate_node):
            continue
        spec = space.schema["doc_types"][doc.doc_type]
        if spec["gate_blocking"] and doc_status(doc) not in ("approved", "superseded"):
            err(rel, 1, f"gate-blocking doc is {doc_status(doc)}, not approved",
                "approve or supersede every gate-blocking doc in the subtree")

    for type_name in ("process", "rule_set", "acceptance_set"):
        exists = any(doc_in_node(space, rel, gate_node)
                     and space.docs[rel].doc_type == type_name
                     for rel in space.docs)
        if not exists:
            anchor = node_overview_rel(space.schema, gate_node)
            err(anchor, 1, f"subtree holds no {type_name} document",
                "the distributed brief contract requires processes, rules"
                " and acceptance criteria")

    if gate_node:
        for rel in sorted(space.docs):
            doc = space.docs[rel]
            if not doc_in_node(space, rel, gate_node):
                continue
            for _lineno, id_value, _target, _is_wiki in id_references(doc):
                info = space.ids.get(id_value)
                if info is None or doc_in_node(space, info["doc"], gate_node):
                    continue
                owner = space.docs[info["doc"]]
                if doc_status(owner) != "approved":
                    err(rel, _lineno,
                        f"cites {id_value} whose owning doc {info['doc']} is"
                        f" {doc_status(owner)}",
                        "cross-domain citation closure: cited owners are approved")


# ---------------------------------------------------------------------------
# Render
# ---------------------------------------------------------------------------


def statement_of(space: Space, id_value: str) -> str:
    info = space.ids[id_value]
    row = info["row"]
    for column in ("statement", "criterion", "question", "ruling", "finding"):
        if column in row:
            return row[column]
    return ""


def id_sort_key(id_value: str):
    m = NAMESPACED_ID_RE.fullmatch(id_value)
    if m:
        return (m.group(1), m.group(2), int(m.group(3)))
    return ("ZZ", "ZZZZ", 0)


def node_rollup(space: Space, node_rel: str) -> str:
    ranks = []
    for rel in space.docs:
        if not doc_in_node(space, rel, node_rel):
            continue
        status = doc_status(space.docs[rel])
        if status == "superseded":
            continue
        ranks.append(STATUS_RANK.get(status, 0))
    if not ranks:
        return "draft"
    for name, rank in STATUS_RANK.items():
        if rank == min(ranks):
            return name
    return "draft"


def foundation_approved(space: Space) -> bool:
    return all(doc_status(space.docs[n]) == "approved"
               for n in root_file_rels(space.schema)
               if n in space.docs)


def node_buildable(space: Space, node_rel: str) -> bool:
    probe = run_gate_checks_collect(space, node_rel)
    return foundation_approved(space) and not probe


def run_gate_checks_collect(space: Space, node_rel: str) -> list[Finding]:
    collected: list[Finding] = []
    run_gate_checks(space, collected, node_rel)
    return [f for f in collected if f.severity == "error"]


def cited_by_map(space: Space) -> dict[str, list[str]]:
    cited: dict[str, list[str]] = {}
    for ac_id in sorted((i for i in space.ids
                         if space.ids[i]["kind"] == "AC"), key=id_sort_key):
        cites = space.ids[ac_id]["row"].get("cites", "")
        for m in NAMESPACED_ID_RE.finditer(cites):
            cited.setdefault(m.group(0), []).append(ac_id)
    return cited


def render_views(space: Space, warnings: list[Finding]) -> dict[str, str]:
    """Pure function of the authored tree (plus stable warnings): returns
    {relpath under _generated: content}."""
    docs_sorted = sorted(space.docs)
    cited = cited_by_map(space)
    vault_prefix = ""
    if space.vault_root is not None:
        try:
            vault_prefix = space.root.resolve().relative_to(
                space.vault_root.resolve()).as_posix() + "/"
        except ValueError:
            vault_prefix = ""
    space_rel = space_overview_rel(space.schema)
    title = str(space.docs.get(space_rel).fm.get("title", "")) \
        if space_rel in space.docs else ""
    stable_warnings = [w for w in warnings if w.severity == "warning"]

    lines = [GENERATED_MARKER, f"# Index: {title}", ""]
    lines.append(f"Foundation approved: {'yes' if foundation_approved(space) else 'no'}")
    lines.append(f"Space status: {node_rollup(space, '')}")
    lines += ["", "## Nodes", "",
              "| node | code | status | buildable | docs |",
              "|---|---|---|---|---|"]
    for node_rel in sorted(space.nodes):
        count = sum(1 for r in space.docs if space.docs[r].node == node_rel)
        lines.append(
            f"| {node_rel or '(root)'} | {space.nodes[node_rel]} |"
            f" {node_rollup(space, node_rel)} |"
            f" {'yes' if node_buildable(space, node_rel) else 'no'} | {count} |")
    lines += ["", "## Documents", "",
              "| doc | type | status | summary |",
              "|---|---|---|---|"]
    for rel in docs_sorted:
        doc = space.docs[rel]
        summary = ""
        for h_idx, level, _text in doc.headings:
            if level == 1:
                for i in range(h_idx + 1, len(doc.lines) + 1):
                    candidate = doc.lines[i - 1].strip()
                    if candidate.startswith("#"):
                        break
                    if candidate:
                        summary = candidate.replace("|", "\\|")
                        break
                break
        cell = (f"[[{vault_prefix}{rel[:-3]}\\|{rel}]]" if vault_prefix
                else f"[{rel}]({'../' + rel})")
        lines.append(f"| {cell} | {doc.doc_type} |"
                     f" {doc_status(doc)} | {summary} |")
    if stable_warnings:
        lines += ["", "## Warnings", ""]
        for w in sorted(stable_warnings, key=lambda f: (f.path, f.line, f.check)):
            lines.append(f"- {w.path}:{w.line} [{w.check}] {w.message}")
    index_md = "\n".join(lines) + "\n"

    lines = [GENERATED_MARKER, f"# Registry: {title}", "", "## Codes", "",
             "| code | node |", "|---|---|"]
    for node_rel in sorted(space.nodes, key=lambda n: (space.nodes[n], n)):
        if space.nodes[node_rel]:
            lines.append(f"| {space.nodes[node_rel]} | {node_rel or '(root)'} |")
    for kind, heading in (("BR", "Business Rules"), ("AC", "Acceptance Criteria"),
                          ("AS", "Assumptions"), ("DEC", "Decisions")):
        ids = sorted((i for i in space.ids if space.ids[i]["kind"] == kind),
                     key=id_sort_key)
        if not ids:
            continue
        lines += ["", f"## {heading}", ""]
        if kind == "BR":
            lines += ["| id | statement | status | doc | cited_by |", "|---|---|---|---|---|"]
            for i in ids:
                info = space.ids[i]
                lines.append(f"| {i} | {statement_of(space, i).replace('|', chr(92) + '|')} |"
                             f" {info['row'].get('status', '')} | {info['doc']} |"
                             f" {', '.join(cited.get(i, []))} |")
        else:
            lines += ["| id | statement | status | doc |", "|---|---|---|---|"]
            for i in ids:
                info = space.ids[i]
                status = info["row"].get("status", info["row"].get("severity", ""))
                lines.append(f"| {i} | {statement_of(space, i).replace('|', chr(92) + '|')} |"
                             f" {status} | {info['doc']} |")
    registry_md = "\n".join(lines) + "\n"

    def semantic_hash(doc: Document) -> str:
        text = doc.abs_path.read_text(encoding="utf-8")
        for start, end in GENERATED_BODY_BLOCKS:
            text = re.sub(r"\n*" + re.escape(start) + r".*?"
                          + re.escape(end) + r"\n*", "\n\n", text,
                          flags=re.DOTALL)
        # Package lifecycle stamps are compiler-owned receipt metadata, not
        # authored semantic input. Keeping them in registry source hashes
        # would make approval self-invalidating: the package hash includes the
        # registry, while the registry would change only because its own stamp
        # was added to space.md.
        if doc.rel == space_rel:
            text = re.sub(
                r"(?m)^(?:package_status|package_hash|package_approved_at_utc|"
                r"package_contract_version):[^\n]*\n?", "", text,
            )
        text = text.rstrip() + "\n"
        return "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()

    registry = {"schema_version": space.schema["schema_version"],
                "codes": {space.nodes[n]: (n or "(root)")
                          for n in space.nodes if space.nodes[n]},
                "ids": {},
                "source_hashes": {
                    rel: semantic_hash(space.docs[rel]) for rel in docs_sorted
                }}
    for i in sorted(space.ids, key=id_sort_key):
        info = space.ids[i]
        statement = statement_of(space, i)
        registry["ids"][i] = {
            "kind": info["kind"],
            "doc": info["doc"],
            "row_status": info["row"].get("status",
                                          info["row"].get("severity", "")),
            "doc_status": doc_status(space.docs[info["doc"]]),
            "statement": statement,
            "statement_sha256": hashlib.sha256(statement.encode("utf-8")).hexdigest(),
            "cited_by": cited.get(i, []),
        }
    registry_json = json.dumps(registry, indent=2, sort_keys=True) + "\n"

    inbound: dict[str, list[str]] = {}
    for rel in docs_sorted:
        doc = space.docs[rel]
        edges = []
        for _lineno, _text, target in doc.links:
            clean = target.split("#", 1)[0]
            if not clean or target.startswith(("http://", "https://", "mailto:", "#")):
                continue
            edges.append((doc.abs_path.parent / clean).resolve())
        for _lineno, _embed, target, _anchor, _alias in doc.wikilinks:
            if target and space.vault_root is not None:
                edges.append((space.vault_root / (target + ".md")).resolve())
        for resolved in edges:
            try:
                target_rel = resolved.relative_to(space.root.resolve()).as_posix()
            except ValueError:
                continue
            if target_rel in space.docs and target_rel != rel:
                inbound.setdefault(target_rel, [])
                if rel not in inbound[target_rel]:
                    inbound[target_rel].append(rel)
    lines = [GENERATED_MARKER, f"# Backlinks: {title}", ""]
    for rel in docs_sorted:
        sources = sorted(inbound.get(rel, []))
        if not sources:
            continue
        lines.append(f"## {rel}")
        lines += [f"- {s}" for s in sources]
        lines.append("")
    backlinks_md = "\n".join(lines).rstrip("\n") + "\n"

    lines = [GENERATED_MARKER, f"# Status: {title}", "", "## Documents by status", "",
             "| type | draft | in_review | approved | superseded |",
             "|---|---|---|---|---|"]
    for type_name in sorted(space.schema["doc_types"]):
        counts = {s: 0 for s in space.schema["statuses"]}
        for rel in docs_sorted:
            if space.docs[rel].doc_type == type_name:
                status = doc_status(space.docs[rel])
                if status in counts:
                    counts[status] += 1
        if sum(counts.values()):
            lines.append(f"| {type_name} | {counts['draft']} | {counts['in_review']} |"
                         f" {counts['approved']} | {counts['superseded']} |")
    status_md = "\n".join(lines) + "\n"

    groups = {"open": [], "deferred": [], "answered": []}
    for i in sorted((x for x in space.ids if space.ids[x]["kind"] == "OQ"),
                    key=id_sort_key):
        info = space.ids[i]
        status = info["row"].get("status", "")
        if status in groups:
            groups[status].append(i)
    lines = [GENERATED_MARKER, f"# Open Questions: {title}", ""]
    for group, heading in (("open", "Open"), ("deferred", "Deferred"),
                           ("answered", "Answered (last 20)")):
        ids = groups[group]
        if group == "answered":
            ids = ids[-20:]
        if not ids:
            continue
        lines += [f"## {heading}", "",
                  "| id | question | doc | opened_on | note |", "|---|---|---|---|---|"]
        for i in ids:
            info = space.ids[i]
            row = info["row"]
            lines.append(f"| {i} | {row.get('question', '').replace('|', chr(92) + '|')} |"
                         f" {info['doc']} | {row.get('opened_on', '')} |"
                         f" {row.get('note', '').replace('|', chr(92) + '|')} |")
        lines.append("")
    questions_md = "\n".join(lines).rstrip("\n") + "\n"

    return {"index.md": index_md, "registry.md": registry_md,
            "registry.json": registry_json, "backlinks.md": backlinks_md,
            "status.md": status_md, "open-questions.md": questions_md}


def freshness_findings(space: Space, warnings: list[Finding]) -> list[Finding]:
    rendered = render_views(space, warnings)
    findings: list[Finding] = []
    gen_dir = space.root / GENERATED_DIR
    for name, content in rendered.items():
        on_disk = gen_dir / name
        if not on_disk.is_file() or \
                on_disk.read_text(encoding="utf-8", errors="replace") != content:
            findings.append(Finding(
                "error", f"{GENERATED_DIR}/{name}", 1, "generated_freshness",
                "generated view is stale or missing",
                "run the render subcommand"))
    return findings


# ---------------------------------------------------------------------------
# Output
# ---------------------------------------------------------------------------


def emit(findings: list[Finding], as_json: bool) -> int:
    ordered = sorted(findings, key=lambda f: (f.path, f.line, f.check, f.message))
    errors = sum(1 for f in ordered if f.severity == "error")
    warnings = len(ordered) - errors
    for f in ordered:
        if as_json:
            print(json.dumps({"severity": f.severity, "path": f.path,
                              "line": f.line, "check": f.check,
                              "message": f.message, "fix": f.remediation},
                             sort_keys=True))
        else:
            print(f"{f.severity.upper()} {f.path}:{f.line} [{f.check}]"
                  f" {f.message} | Fix: {f.remediation}")
    if not as_json:
        print(f"ba_compile: {errors} error(s), {warnings} warning(s)")
    return 1 if errors else 0


def load_schema(path: Path) -> dict:
    schema = json.loads(path.read_text(encoding="utf-8"))
    if schema.get("schema_version") != 5:
        raise SystemExit(f"ba_compile: unknown schema_version in {path}")
    return schema


# ---------------------------------------------------------------------------
# Stubs
# ---------------------------------------------------------------------------


def table_skeleton(columns: list[str]) -> list[str]:
    return ["| " + " | ".join(columns) + " |",
            "|" + "---|" * len(columns)]


def humanize(target: str) -> str:
    return target.rsplit("/", 1)[-1].replace("-", " ").title()


def stub_lines(schema: dict, doc_type: str, title: str,
               vault_prefix: str = "", nav_hub: str = "",
               aliases: list[str] | None = None,
               seed_rows: dict[str, list[str]] | None = None,
               **extra) -> list[str]:
    spec = schema["doc_types"][doc_type]
    fm = ["---", f"type: {doc_type}", f"title: {title}", "status: draft",
          "owner_role: business_analyst"]
    for key in spec["extra_frontmatter"]["required"]:
        value = extra.get(key)
        if isinstance(value, list):
            fm.append(f"{key}:")
            for v in value:
                if key in ("governs", "verifies"):
                    target = str(v).strip()
                    if target.endswith(".md"):
                        target = target[:-3]
                    fm.append(f'  - "[[{vault_prefix}{target}]]"')
                else:
                    fm.append(f"  - {v}")
        else:
            fm.append(f"{key}: {value}")
    fm += ["tags:", f"  - doc/{doc_type.replace('_', '-')}", "  - status/draft"]
    if aliases:
        fm.append("aliases:")
        fm.extend(f"  - {a}" for a in aliases)
    fm.append("---")
    body = ["", f"# {title}", "", f"One-line summary of {title}.", ""]
    section_titles = {token: token.replace("_", " ").title()
                      for token in spec["required_sections"]}
    row_by_section = {schema["row_schemas"][k.lower()]["section"]: k
                      for k in spec["mints"]
                      if schema["row_schemas"][k.lower()]["section"] in spec["required_sections"]}
    for token in spec["required_sections"]:
        body.append(f"## {section_titles[token]} <!-- sec: {token} -->")
        body.append("")
        kind = row_by_section.get(token)
        if kind:
            body += table_skeleton(schema["row_schemas"][kind.lower()]["columns"])
            if seed_rows and token in seed_rows:
                body.append("| " + " | ".join(seed_rows[token]) + " |")
        else:
            body.append("To be analyzed.")
        body.append("")
    # Nav first link: the owning hub per the vault's hub ladder; overview
    # docs (hubs themselves) and callers without a hub keep the subtree map.
    nav_target = nav_hub or "maps/business-analysis"
    body += ["## Navigation <!-- sec: nav -->", "",
             f"[[{nav_target}|{humanize(nav_target)}]]", ""]
    return fm + body


def write_stub(schema: dict, path: Path, doc_type: str, title: str,
               vault_prefix: str = "", nav_hub: str = "",
               aliases: list[str] | None = None,
               seed_rows: dict[str, list[str]] | None = None,
               **extra) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(
        stub_lines(schema, doc_type, title, vault_prefix, nav_hub,
                   aliases, seed_rows, **extra)
    ).rstrip("\n") + "\n", encoding="utf-8")


def next_ids(space: Space, code: str) -> dict[str, str]:
    result = {}
    for kind in ("BR", "AC", "AS", "OQ", "DEC"):
        highest = 0
        for id_value in space.ids:
            m = NAMESPACED_ID_RE.fullmatch(id_value)
            if m and m.group(1) == kind and m.group(2) == code:
                highest = max(highest, int(m.group(3)))
        result[kind] = f"{kind}-{code}-{highest + 1:03d}"
    return result


# ---------------------------------------------------------------------------
# Subcommands
# ---------------------------------------------------------------------------


def resolve_vault_root(space_dir: Path, override: str) -> Path | None:
    """The vault root: --vault-root, else the nearest ancestor named
    docs. No silent fallback: a wikilink-resolving run without a vault
    root is a usage error, not a guess."""
    if override:
        return Path(override).resolve()
    for ancestor in space_dir.resolve().parents:
        if ancestor.name == "docs":
            return ancestor
    return None


def require_vault_root(args) -> Path | None:
    root = resolve_vault_root(Path(args.space), getattr(args, "vault_root", ""))
    if root is None:
        print("ba_compile: FAIL: no ancestor named docs and no --vault-root;"
              " wikilink resolution needs the vault root named explicitly",
              file=sys.stderr)
    return root


def vault_prefix_for(space_dir: Path, vault_root: Path) -> str:
    try:
        return space_dir.resolve().relative_to(
            vault_root.resolve()).as_posix() + "/"
    except ValueError:
        return ""


def cmd_init(args, schema: dict) -> int:
    space_dir = Path(args.space)
    if space_dir.is_dir() and any(space_dir.iterdir()):
        print(f"ba_compile: FAIL: {space_dir} already exists and is not empty",
              file=sys.stderr)
        return 1
    vault_root = require_vault_root(args)
    if vault_root is None:
        return 2
    prefix = vault_prefix_for(space_dir, vault_root)
    hub = f"{prefix}{space_overview_rel(schema)[:-3]}"
    (space_dir / GENERATED_DIR).mkdir(parents=True, exist_ok=True)
    write_stub(schema, space_dir / space_overview_rel(schema), "space",
               args.title, code=args.code, aliases=[args.code])
    write_stub(schema, space_dir / named_file_name(schema, "glossary"),
               "glossary", f"{args.title} Glossary", nav_hub=hub)
    write_stub(schema, space_dir / named_file_name(schema, "actor_roster"),
               "actor_roster", f"{args.title} Actors", nav_hub=hub)
    budgets_name = named_file_name(schema, "budget_set")
    write_stub(schema, space_dir / budgets_name, "budget_set",
               f"{args.title} Non-Functional Budgets", nav_hub=hub,
               scope="space")
    budgets_path = space_dir / budgets_name
    budgets_path.write_text(
        budgets_path.read_text(encoding="utf-8")
        .replace("To be analyzed.", "None stated, confirmed."),
        encoding="utf-8")
    print(f"ba_compile: space initialized at {space_dir} (code {args.code})")
    return 0


def cmd_stub(args, schema: dict) -> int:
    if args.type not in schema["doc_types"]:
        print(f"ba_compile: FAIL: unknown type '{args.type}'", file=sys.stderr)
        return 2
    vault_root = require_vault_root(args)
    if vault_root is None:
        return 2
    space_dir = Path(args.space)
    prefix = vault_prefix_for(space_dir, vault_root)
    spec = schema["doc_types"][args.type]
    loc = spec["location"]
    node = args.node.strip("/")
    title = args.title
    extra: dict = {}
    aliases: list[str] | None = None
    seed_rows: dict[str, list[str]] | None = None
    # Overview docs are hubs and nav to the subtree map (the default);
    # everything else navs to its owning node's overview hub.
    nav_hub = ("" if args.type in ("space", "domain")
               else f"{prefix}{node_overview_rel(schema, node)[:-3]}")
    if args.type == "domain":
        if not node:
            print("ba_compile: FAIL: domain stubs need --node domains/<slug>",
                  file=sys.stderr)
            return 2
        target = space_dir / node / named_file_name(schema, "domain")
        extra["code"] = args.code or ""
        aliases = [args.code] if args.code else None
    elif loc["kind"] == "named_file":
        name = named_file_name(schema, args.type)
        target = space_dir / node / name if node else space_dir / name
        if args.type == "budget_set":
            extra["scope"] = "domain" if node else "space"
        if args.type == "space":
            extra["code"] = args.code or ""
            aliases = [args.code] if args.code else None
    elif args.type == "decision":
        if not args.slug:
            print("ba_compile: FAIL: folder docs need --slug", file=sys.stderr)
            return 2
        pre_space, _ = scan_space(space_dir, schema)
        code = nearest_code(pre_space, node)
        if not code:
            print("ba_compile: FAIL: decision stubs need an owning node"
                  " code; declare the node overview first", file=sys.stderr)
            return 2
        # The id is minted in the ruling row and the alias; the filename
        # and the title stay natural (display-native naming).
        dec_id = next_ids(pre_space, code)["DEC"]
        base = space_dir / node if node else space_dir
        target = (base / loc["folder"]
                  / f"{args.slug}-{loc['filename_suffix']}.md")
        aliases = [dec_id]
        seed_rows = {"ruling": [dec_id, "To be decided.", "active",
                                utc_today().isoformat()]}
    else:
        if not args.slug:
            print("ba_compile: FAIL: folder docs need --slug", file=sys.stderr)
            return 2
        base = space_dir / node if node else space_dir
        suffix = loc.get("filename_suffix")
        name = f"{args.slug}-{suffix}.md" if suffix else f"{args.slug}.md"
        target = base / loc["folder"] / name
    if args.type == "rule_set":
        if not args.governs:
            print("ba_compile: FAIL: rule_set stubs need --governs", file=sys.stderr)
            return 2
        extra["governs"] = args.governs.split(",")
    if args.type == "acceptance_set":
        if not args.verifies:
            print("ba_compile: FAIL: acceptance_set stubs need --verifies",
                  file=sys.stderr)
            return 2
        extra["verifies"] = args.verifies.split(",")
    if args.type == "integration":
        extra["system_name"] = args.slug or ""
        extra["direction"] = args.direction
    if target.exists():
        print(f"ba_compile: FAIL: {target} already exists", file=sys.stderr)
        return 1
    write_stub(schema, target, args.type, title, vault_prefix=prefix,
               nav_hub=nav_hub, aliases=aliases, seed_rows=seed_rows,
               **extra)
    space, _ = scan_space(space_dir, schema)
    code = nearest_code(space, node)
    print(f"ba_compile: created {target}")
    if code:
        free = next_ids(space, code)
        print("ba_compile: next free ids: "
              + ", ".join(free[k] for k in sorted(free)))
    return 0


def cmd_check(args, schema: dict) -> int:
    vault_root = require_vault_root(args)
    if vault_root is None:
        return 2
    space, base = scan_space(Path(args.space), schema)
    space.vault_root = vault_root
    findings = run_checks(space, base, gate=args.gate == "approval",
                          gate_node=args.node)
    if not space.broken:
        warnings = [f for f in findings if f.severity == "warning"]
        findings += freshness_findings(space, warnings)
    return emit(findings, args.json)


def restamp_frontmatter(text: str, stamps: dict) -> str | None:
    """Set the given frontmatter keys in place (replace or insert before the
    closing delimiter), preserving everything else byte for byte."""
    lines = text.splitlines(keepends=True)
    if not lines or lines[0].strip() != "---":
        return None
    close = None
    for i in range(1, len(lines)):
        if lines[i].strip() == "---":
            close = i
            break
    if close is None:
        return None
    remaining = dict(stamps)
    for i in range(1, close):
        key = lines[i].strip().partition(":")[0].strip()
        if key in remaining:
            lines[i] = f"{key}: {remaining.pop(key)}\n"
    lines[close:close] = [f"{k}: {v}\n" for k, v in remaining.items()]
    return "".join(lines)


def remove_frontmatter_keys(text: str, keys: set[str]) -> str | None:
    """Remove scalar frontmatter keys while preserving all other bytes."""
    lines = text.splitlines(keepends=True)
    if not lines or lines[0].strip() != "---":
        return None
    close = next((i for i in range(1, len(lines))
                  if lines[i].strip() == "---"), None)
    if close is None:
        return None
    kept = [lines[0]]
    kept.extend(line for line in lines[1:close]
                if line.strip().partition(":")[0].strip() not in keys)
    kept.extend(lines[close:])
    return "".join(kept)


def atomic_replace(path: Path, text: str) -> None:
    """Replace one authored note atomically without leaving a partial file."""
    mode = path.stat().st_mode & 0o777
    descriptor, temporary = tempfile.mkstemp(prefix=f".{path.name}.",
                                             dir=path.parent)
    temporary_path = Path(temporary)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temporary_path, mode)
        os.replace(temporary_path, path)
    except OSError:
        try:
            temporary_path.unlink()
        except FileNotFoundError:
            pass
        raise


def draft_document_text(text: str) -> str | None:
    updated = restamp_frontmatter(text, {"status": "draft"})
    if updated is None:
        return None
    updated = re.sub(r"(?m)^(\s*- status/)[a-z0-9-]+\s*$",
                     r"\g<1>draft", updated, count=1)
    return remove_frontmatter_keys(updated, {"approved_at"})


def draft_package_text(text: str) -> str | None:
    updated = restamp_frontmatter(text, {"package_status": "draft"})
    if updated is None:
        return None
    return remove_frontmatter_keys(
        updated, {"package_hash", "package_approved_at_utc"})


def package_hash(space_dir: Path) -> str:
    """Hash the complete BA package, including the rendered registry.

    Lifecycle stamps deliberately sit outside the digest so approval is
    atomic: writing the stamp does not immediately make the stamp stale.
    """
    digest = hashlib.sha256()
    ignored = {"package_hash", "package_status", "package_approved_at_utc",
               "package_contract_version"}
    for path in sorted(space_dir.rglob("*.md")):
        text = path.read_text(encoding="utf-8")
        props, body_line, error = parse_frontmatter(text)
        if not error and props:
            lines = text.splitlines()
            kept = ["---"]
            for raw in lines[1:body_line - 2]:
                if raw.partition(":")[0].strip() not in ignored:
                    kept.append(raw)
            kept.extend(lines[body_line - 1:])
            text = "\n".join(kept).rstrip() + "\n"
        digest.update(path.relative_to(space_dir).as_posix().encode())
        digest.update(b"\0")
        digest.update(text.encode())
        digest.update(b"\0")
    registry = space_dir / "_generated" / "registry.json"
    if registry.is_file():
        digest.update(registry.relative_to(space_dir).as_posix().encode())
        digest.update(b"\0")
        digest.update(registry.read_bytes())
        digest.update(b"\0")
    return "sha256:" + digest.hexdigest()


def classify_package(space_dir: Path, schema: dict | None = None,
                     vault_root: Path | None = None) -> dict:
    """Return the one BA receipt-verification verdict used by all consumers."""
    schema = schema or load_schema(DEFAULT_SCHEMA)
    space, base = scan_space(space_dir, schema)
    space.vault_root = vault_root or resolve_vault_root(space_dir, "")
    root = space.docs.get(space_overview_rel(schema))
    props = root.fm if root else {}
    digest = package_hash(space_dir) if space_dir.is_dir() else ""
    findings = run_checks(space, base, gate=True)
    if not space.broken:
        warnings = [item for item in findings if item.severity == "warning"]
        findings += freshness_findings(space, warnings)
    errors = [item for item in findings if item.severity == "error"]
    try:
        version = int(props.get("package_contract_version", 0) or 0)
    except (TypeError, ValueError):
        version = 0
    approved_hash = (props.get("package_status") == "approved"
                     and props.get("package_hash") == digest)
    strict_current = approved_hash and version >= 2 and not errors
    authored = [path for path in space_dir.rglob("*.md")
                if GENERATED_DIR not in path.parts] if space_dir.is_dir() else []
    pre_contract_legacy = (
        (not props.get("package_status") and bool(authored) and all(
            parse_frontmatter(path.read_text(encoding="utf-8"))[0].get("status")
            in {"approved", "superseded"} for path in authored))
        or (approved_hash and version < 2)
    )

    def decision_gate_error(item: Finding) -> bool:
        doc = space.docs.get(item.path)
        return (item.check == "gate_approval" and doc is not None
                and doc.doc_type == "decision"
                and doc_status(doc) not in {"approved", "superseded"})

    v2_decision_migration = (approved_hash and version == 2 and bool(errors)
                             and all(decision_gate_error(item) for item in errors))
    if strict_current:
        profile, legacy_reason = "strict-current", ""
    elif pre_contract_legacy:
        profile, legacy_reason = "legacy-readonly", "pre-contract"
    elif v2_decision_migration:
        profile, legacy_reason = "legacy-readonly", "v2-decision-gate"
    else:
        profile, legacy_reason = "invalid", ""
    return {
        "package_hash": digest,
        "profile": profile,
        "legacy": profile == "legacy-readonly",
        "current": profile in {"strict-current", "legacy-readonly"},
        "legacy_reason": legacy_reason,
        "findings": findings,
    }


def cmd_approve(args, schema: dict) -> int:
    """Approve a doc: the script stamps status and the UTC date, then
    re-runs the checks; a doc the compiler rejects is restored untouched.
    The model never types the date."""
    space_dir = Path(args.space)
    vault_root = require_vault_root(args)
    if vault_root is None:
        return 2
    space, base = scan_space(space_dir, schema)
    space.vault_root = vault_root
    rel = args.doc
    doc = space.docs.get(rel)
    if doc is None:
        print(f"ba_compile: FAIL: unknown doc '{rel}' in space {space_dir}",
              file=sys.stderr)
        return 2
    status = doc_status(doc)
    if status in ("approved", "superseded"):
        print(f"ba_compile: FAIL: {rel} is already {status}", file=sys.stderr)
        return 1
    if status != "in_review":
        print(f"ba_compile: FAIL: {rel} is '{status}', not in_review;"
              " approval follows review, flip the doc to in_review first",
              file=sys.stderr)
        return 1
    target = doc.abs_path
    original = target.read_text(encoding="utf-8")
    today = utc_today().isoformat()
    stamps: dict = {"status": "approved", "approved_at": today}
    updated = restamp_frontmatter(original, stamps)
    if updated is None:
        print(f"ba_compile: FAIL: {rel} has no parseable frontmatter block",
              file=sys.stderr)
        return 1
    # The tag mirror rides the same write (one-clock, one operation).
    updated = re.sub(r"(?m)^(\s*- status/)[a-z0-9-]+\s*$",
                     r"\g<1>approved", updated, count=1)
    target.write_text(updated, encoding="utf-8")
    space, base = scan_space(space_dir, schema)
    space.vault_root = vault_root
    findings = run_checks(space, base)
    blocking = [f for f in findings
                if f.severity == "error" and f.path == rel]
    if blocking:
        target.write_text(original, encoding="utf-8")
        emit(blocking, args.json)
        print(f"ba_compile: FAIL: {rel} does not pass the checks as"
              " approved; original restored", file=sys.stderr)
        return 1
    print(f"ba_compile: approved {rel} (approved_at {today})")
    return 0


def cmd_approve_package(args, schema: dict) -> int:
    """Close the whole BA space as one handoff package."""
    vault_root = require_vault_root(args)
    if vault_root is None:
        return 2
    space_dir = Path(args.space)
    # Generated registry is part of the receipt and must be fresh before the
    # gate is evaluated.
    render_args = argparse.Namespace(space=args.space, vault_root=args.vault_root,
                                    check_only=False, json=False)
    if cmd_render(render_args, schema):
        return 1
    space, base = scan_space(space_dir, schema)
    space.vault_root = vault_root
    findings = run_checks(space, base, gate=True)
    if not space.broken:
        warnings = [f for f in findings if f.severity == "warning"]
        findings += freshness_findings(space, warnings)
    errors = [f for f in findings if f.severity == "error"]
    if errors:
        return emit(errors, getattr(args, "json", False))
    root_rel = space_overview_rel(schema)
    root_doc = space.docs.get(root_rel)
    if root_doc is None:
        print("ba_compile: FAIL: space overview is missing", file=sys.stderr)
        return 1
    if str(root_doc.fm.get("package_status", "")) == "approved":
        print("ba_compile: FAIL: approved package needs begin-revision", file=sys.stderr)
        return 1
    target = root_doc.abs_path
    original = target.read_text(encoding="utf-8")
    updated = restamp_frontmatter(original, {
        "package_status": "approved",
        "package_contract_version": PACKAGE_CONTRACT_VERSION,
        "package_hash": package_hash(space_dir),
        "package_approved_at_utc": utc_today().isoformat(),
    })
    if updated is None:
        return 1
    try:
        atomic_replace(target, updated)
    except OSError as exc:
        print(f"ba_compile: FAIL: package receipt write failed: {exc}",
              file=sys.stderr)
        return 1
    expected = package_hash(space_dir)
    props, _body_line, error = parse_frontmatter(target.read_text(encoding="utf-8"))
    if error or props.get("package_hash") != expected:
        try:
            atomic_replace(target, original)
        except OSError as exc:
            print(f"ba_compile: FAIL: package approval hash closing check failed;"
                  f" receipt restore also failed: {exc}", file=sys.stderr)
            return 1
        print("ba_compile: FAIL: package approval hash closing check failed", file=sys.stderr)
        return 1
    print(json.dumps({"stage": "business-analysis",
                      "result_ref": f"business-analysis/{space_dir.name}/space",
                      "result_type": "business-analysis-package",
                      "package_hash": expected, "status": "approved",
                      "current": True, "verification_profile": "strict-current",
                      "legacy": False}, sort_keys=True))
    return 0


def cmd_begin_revision(args, schema: dict) -> int:
    vault_root = require_vault_root(args)
    if vault_root is None:
        return 2
    space, _base = scan_space(Path(args.space), schema)
    space.vault_root = vault_root
    target = space.docs.get(args.doc)
    if target is None:
        print(f"ba_compile: FAIL: unknown doc '{args.doc}'", file=sys.stderr)
        return 2
    overview = space.docs.get(space_overview_rel(schema))
    root_status = str(overview.fm.get("package_status", "")) if overview else ""
    if overview is None or root_status not in {"approved", "draft", ""}:
        print("ba_compile: FAIL: only an approved, draft, or legacy-approved"
              " package can begin a revision", file=sys.stderr)
        return 1
    classification = classify_package(Path(args.space), schema, vault_root)
    decision_migration = (
        classification["legacy_reason"] == "v2-decision-gate"
        and target.doc_type == "decision"
        and doc_status(target) in {"draft", "in_review"}
    )
    if doc_status(target) not in {"approved", "superseded"} and not decision_migration:
        print("ba_compile: FAIL: begin-revision requires an approved or"
              " superseded document", file=sys.stderr)
        return 1
    root_original = overview.abs_path.read_text(encoding="utf-8")
    root_updated = draft_package_text(root_original)
    if root_updated is None:
        print("ba_compile: FAIL: space overview has no parseable frontmatter block",
              file=sys.stderr)
        return 1
    target_original = target.abs_path.read_text(encoding="utf-8")
    target_updated = target_original if decision_migration else draft_document_text(target_original)
    if target_updated is None:
        print(f"ba_compile: FAIL: {args.doc} has no parseable frontmatter block",
              file=sys.stderr)
        return 1
    if target.abs_path == overview.abs_path:
        combined = draft_document_text(root_updated)
        if combined is None:
            print("ba_compile: FAIL: space overview has no parseable frontmatter block",
                  file=sys.stderr)
            return 1
        try:
            atomic_replace(overview.abs_path, combined)
        except OSError as exc:
            print(f"ba_compile: FAIL: revision write failed: {exc}", file=sys.stderr)
            return 1
        print(f"ba_compile: began package revision at {args.doc}")
        return 0
    try:
        atomic_replace(overview.abs_path, root_updated)
    except OSError as exc:
        print(f"ba_compile: FAIL: package invalidation failed: {exc}", file=sys.stderr)
        return 1
    if decision_migration:
        print(f"ba_compile: began package revision at {args.doc}")
        return 0
    try:
        atomic_replace(target.abs_path, target_updated)
    except OSError as exc:
        try:
            atomic_replace(overview.abs_path, root_original)
        except OSError as restore_exc:
            print(f"ba_compile: FAIL: revision target write failed: {exc};"
                  f" root remains draft because restore failed: {restore_exc}",
                  file=sys.stderr)
            return 1
        print(f"ba_compile: FAIL: revision target write failed: {exc};"
              " original package receipt restored", file=sys.stderr)
        return 1
    print(f"ba_compile: began package revision at {args.doc}")
    return 0


def cmd_status(args, schema: dict) -> int:
    vault_root = require_vault_root(args)
    if vault_root is None:
        return 2
    classification = classify_package(Path(args.space), schema, vault_root)
    current = classification["current"]
    value = {"stage": "business-analysis",
             "result_ref": f"business-analysis/{Path(args.space).name}/space",
             "result_type": "business-analysis-package",
             "package_hash": classification["package_hash"],
             "status": "approved" if current else "draft",
             "current": current,
             "verification_profile": classification["profile"],
             "legacy": classification["legacy"]}
    print(json.dumps(value, indent=2, sort_keys=True))
    return 0 if current else 1


def cmd_render(args, schema: dict) -> int:
    vault_root = require_vault_root(args)
    if vault_root is None:
        return 2
    space, base = scan_space(Path(args.space), schema)
    space.vault_root = vault_root
    if space.broken:
        emit([f for f in base if f.severity == "error"], args.json)
        print("ba_compile: FAIL: ambiguity findings block render", file=sys.stderr)
        return 1
    findings = run_checks(space, base)
    duplicate = [f for f in findings if f.check == "id_unique"]
    if duplicate:
        emit(duplicate, args.json)
        print("ba_compile: FAIL: duplicate ids block render", file=sys.stderr)
        return 1
    warnings = [f for f in findings if f.severity == "warning"]
    rendered = render_views(space, warnings)
    gen_dir = space.root / GENERATED_DIR
    if args.check_only:
        stale = freshness_findings(space, warnings)
        if stale:
            return emit(stale, args.json)
        print("ba_compile: generated views are fresh")
        return 0
    gen_dir.mkdir(parents=True, exist_ok=True)
    wrote = 0
    for name, content in rendered.items():
        target = gen_dir / name
        if target.is_file() and \
                target.read_text(encoding="utf-8", errors="replace") == content:
            continue
        target.write_text(content, encoding="utf-8")
        wrote += 1
    removed = 0
    for stray in sorted(gen_dir.iterdir()):
        if stray.name not in GENERATED_VIEWS and stray.name != ".gitkeep":
            stray.unlink()
            removed += 1
    print(f"ba_compile: rendered {wrote} view(s), removed {removed} stray file(s),"
          f" {len(rendered) - wrote} unchanged")
    return 0


def cmd_resolve(args, schema: dict) -> int:
    space, _ = scan_space(Path(args.space), schema)
    wanted = [i.strip() for i in args.ids.split(",") if i.strip()]
    result = {}
    missing = []
    for id_value in wanted:
        info = space.ids.get(id_value)
        if info is None:
            missing.append(id_value)
            continue
        statement = statement_of(space, id_value)
        result[id_value] = {
            "doc": info["doc"],
            "doc_status": doc_status(space.docs[info["doc"]]),
            "statement": statement,
            "statement_sha256": hashlib.sha256(statement.encode("utf-8")).hexdigest(),
        }
    print(json.dumps(result, indent=2, sort_keys=True))
    if missing:
        print(f"ba_compile: FAIL: unknown ids: {', '.join(missing)}", file=sys.stderr)
        return 1
    return 0


def cmd_verify_import(args, schema: dict) -> int:
    space, _ = scan_space(Path(args.space), schema)
    data = json.loads(Path(args.json_file).read_text(encoding="utf-8"))
    failures = []
    for entry in data.get("criteria", []):
        criterion = str(entry.get("criterion_id", ""))
        info = space.ids.get(criterion)
        if info is None:
            failures.append(f"{criterion}: not declared in the space")
            continue
        if str(entry.get("disposition", "")) == "deferred":
            continue
        owner_status = doc_status(space.docs[info["doc"]])
        if owner_status != "approved":
            failures.append(f"{criterion}: owning doc {info['doc']} is"
                            f" {owner_status}, not approved")
    for failure in failures:
        print(f"ba_compile: FAIL: {failure}", file=sys.stderr)
    if failures:
        return 1
    print(f"ba_compile: OK: {len(data.get('criteria', []))} criterion id(s) verified")
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Compile and check a business-analysis space.")
    parser.add_argument("--schema", type=Path, default=DEFAULT_SCHEMA)
    sub = parser.add_subparsers(dest="command", required=True)

    p = sub.add_parser("init")
    p.add_argument("--space", required=True)
    p.add_argument("--vault-root", default="", dest="vault_root")
    p.add_argument("--title", required=True)
    p.add_argument("--code", required=True)

    p = sub.add_parser("stub")
    p.add_argument("--space", required=True)
    p.add_argument("--vault-root", default="", dest="vault_root")
    p.add_argument("--type", required=True)
    p.add_argument("--title", required=True)
    p.add_argument("--node", default="")
    p.add_argument("--slug", default="")
    p.add_argument("--code", default="")
    p.add_argument("--governs", default="")
    p.add_argument("--verifies", default="")
    p.add_argument("--direction", default="outbound")

    p = sub.add_parser("check")
    p.add_argument("--space", required=True)
    p.add_argument("--vault-root", default="", dest="vault_root")
    p.add_argument("--gate", choices=["approval"], default="")
    p.add_argument("--node", default="")
    p.add_argument("--json", action="store_true")

    p = sub.add_parser("approve")
    p.add_argument("--space", required=True)
    p.add_argument("--vault-root", default="", dest="vault_root")
    p.add_argument("--doc", required=True)
    p.add_argument("--json", action="store_true")

    p = sub.add_parser("approve-package")
    p.add_argument("--space", required=True)
    p.add_argument("--vault-root", default="", dest="vault_root")
    p.add_argument("--json", action="store_true")

    p = sub.add_parser("begin-revision")
    p.add_argument("--space", required=True)
    p.add_argument("--vault-root", default="", dest="vault_root")
    p.add_argument("--doc", required=True)

    p = sub.add_parser("status")
    p.add_argument("--space", required=True)
    p.add_argument("--vault-root", default="", dest="vault_root")
    p.add_argument("--json", action="store_true")

    p = sub.add_parser("render")
    p.add_argument("--space", required=True)
    p.add_argument("--vault-root", default="", dest="vault_root")
    p.add_argument("--check-only", action="store_true")
    p.add_argument("--json", action="store_true")

    p = sub.add_parser("resolve")
    p.add_argument("--space", required=True)
    p.add_argument("--ids", required=True)
    p.add_argument("--json", action="store_true")

    p = sub.add_parser("verify-import")
    p.add_argument("--space", required=True)
    p.add_argument("--json-file", required=True)

    args = parser.parse_args(argv)
    schema = load_schema(args.schema)
    handlers = {"init": cmd_init, "stub": cmd_stub, "check": cmd_check,
                "approve": cmd_approve, "approve-package": cmd_approve_package,
                "begin-revision": cmd_begin_revision, "status": cmd_status,
                "render": cmd_render,
                "resolve": cmd_resolve, "verify-import": cmd_verify_import}
    return handlers[args.command](args, schema)


if __name__ == "__main__":
    raise SystemExit(main())
